statements:
-- PR9d — WORKFLOW ACTION FAILURE + AMBIGUITY MODEL.
-- See apps/web/supabase/migrations/20260830_action_failure_model.sql for rationale.
-- UNKNOWN/PARTIAL become first-class terminal statuses (unclaimable, identity
-- retained). Phase is monotonic. A terminal outcome is absorbing except through
-- recorded reconciliation. The reaper NEVER requeues a bound action past dispatch.

alter table public.runs drop constraint if exists runs_status_check;
alter table public.runs add constraint runs_status_check check (
  status = any (array['pending','running','done','failed','awaiting_approval',
                      'cancelled','rejected','unknown','partial'])
);

alter table public.runs add column if not exists action_phase            text;
alter table public.runs add column if not exists action_outcome          text;
alter table public.runs add column if not exists dispatch_started_at     timestamptz;
alter table public.runs add column if not exists remote_confirmed_at     timestamptz;
alter table public.runs add column if not exists outcome_recorded_at     timestamptz;
alter table public.runs add column if not exists reconciliation_required boolean not null default false;
alter table public.runs add column if not exists reconciliation_reason   text;
alter table public.runs add column if not exists remote_operation_id     text;
alter table public.runs add column if not exists side_effect_summary     jsonb;

alter table public.runs drop constraint if exists runs_action_phase_vocabulary;
alter table public.runs add constraint runs_action_phase_vocabulary check (
  action_phase is null or action_phase in
    ('PREPARED','PRE_COMMIT_VERIFIED','DISPATCH_STARTED','REMOTE_CONFIRMED','EVIDENCE_RECORDED','COMPLETE')
);

alter table public.runs drop constraint if exists runs_action_outcome_vocabulary;
alter table public.runs add constraint runs_action_outcome_vocabulary check (
  action_outcome is null or action_outcome in
    ('FAILED','SUCCEEDED','UNKNOWN','PARTIAL','SUCCEEDED_EVIDENCE_PENDING','CANCELLED','REJECTED')
);

alter table public.runs drop constraint if exists runs_ambiguous_requires_reconciliation;
alter table public.runs add constraint runs_ambiguous_requires_reconciliation check (
  action_outcome is null
  or action_outcome not in ('UNKNOWN','PARTIAL')
  or reconciliation_required = true
);

alter table public.runs drop constraint if exists runs_dispatch_timestamp_present;
alter table public.runs add constraint runs_dispatch_timestamp_present check (
  action_phase is null
  or action_phase in ('PREPARED','PRE_COMMIT_VERIFIED')
  or dispatch_started_at is not null
);

create index if not exists runs_reconciliation_required_idx
  on public.runs (workflow_instance_id, created_at)
  where reconciliation_required = true;

create or replace function public.action_phase_rank(p text)
returns int language sql immutable set search_path to '' as $$
  select case p
    when 'PREPARED' then 1 when 'PRE_COMMIT_VERIFIED' then 2
    when 'DISPATCH_STARTED' then 3 when 'REMOTE_CONFIRMED' then 4
    when 'EVIDENCE_RECORDED' then 5 when 'COMPLETE' then 6
    else 0 end;
$$;

create table if not exists public.workflow_action_reconciliations (
  id                   uuid primary key default gen_random_uuid(),
  run_id               uuid not null references public.runs(id) on delete cascade,
  workflow_instance_id uuid not null references public.workflow_instances(id),
  action_kind          text not null,
  target_version_hash  text not null,
  idempotency_key      text not null,
  remote_operation_id  text,
  result               text not null check (result in
    ('CONFIRMED_SUCCEEDED','CONFIRMED_NOT_APPLIED','CONFIRMED_PARTIAL','STILL_UNKNOWN')),
  authoritative_system text not null,
  detail               jsonb not null default '{}'::jsonb,
  observed_at          timestamptz not null,
  created_at           timestamptz not null default now()
);

comment on table public.workflow_action_reconciliations is
  'PR9d: read-only answers to "did action X actually happen". Append-only; a reconciliation is the ONLY thing that may resolve UNKNOWN.';

create index if not exists workflow_action_reconciliations_run_idx
  on public.workflow_action_reconciliations (run_id, created_at desc);

alter table public.workflow_action_reconciliations enable row level security;

create or replace function public.reject_reconciliation_mutation()
returns trigger language plpgsql as $$
begin
  raise exception 'workflow_action_reconciliations is append-only (attempted %)', tg_op
    using errcode = 'restrict_violation';
end $$;

drop trigger if exists workflow_action_reconciliations_immutable on public.workflow_action_reconciliations;
create trigger workflow_action_reconciliations_immutable
  before update or delete on public.workflow_action_reconciliations
  for each row execute function public.reject_reconciliation_mutation();

create or replace function public.reconciliation_binding_guard()
returns trigger language plpgsql security definer set search_path to '' as $$
declare r public.runs;
begin
  select * into r from public.runs where id = new.run_id;
  if not found then
    raise exception 'reconciliation: run % does not exist', new.run_id using errcode = 'foreign_key_violation';
  end if;
  if r.workflow_instance_id is null then
    raise exception 'reconciliation: run % is not a bound workflow action', new.run_id
      using errcode = 'restrict_violation';
  end if;
  if new.workflow_instance_id is distinct from r.workflow_instance_id
     or new.action_kind         is distinct from r.action_kind
     or new.target_version_hash is distinct from r.target_version_hash
     or new.idempotency_key     is distinct from r.idempotency_key then
    raise exception 'reconciliation: identity does not match run % (instance/action/target/idempotency)', new.run_id
      using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

drop trigger if exists workflow_action_reconciliations_binding on public.workflow_action_reconciliations;
create trigger workflow_action_reconciliations_binding
  before insert on public.workflow_action_reconciliations
  for each row execute function public.reconciliation_binding_guard();

create or replace function public.runs_action_outcome_guard()
returns trigger language plpgsql security definer set search_path to '' as $$
declare confirmed int;
begin
  if new.workflow_instance_id is null and old.workflow_instance_id is null then
    return new;
  end if;

  if public.action_phase_rank(new.action_phase) < public.action_phase_rank(old.action_phase) then
    raise exception 'runs: action phase cannot move backwards (% → %)',
      old.action_phase, new.action_phase using errcode = 'restrict_violation';
  end if;

  if old.action_outcome is not null and new.action_outcome is distinct from old.action_outcome then
    if old.action_outcome = 'UNKNOWN'
       and new.action_outcome in ('SUCCEEDED','FAILED','PARTIAL') then
      select count(*) into confirmed
        from public.workflow_action_reconciliations x
       where x.run_id = new.id and x.result <> 'STILL_UNKNOWN';
      if confirmed = 0 then
        raise exception
          'runs: UNKNOWN may only be resolved by a recorded reconciliation (run %)', new.id
          using errcode = 'restrict_violation';
      end if;
    elsif old.action_outcome = 'SUCCEEDED_EVIDENCE_PENDING' and new.action_outcome = 'SUCCEEDED' then
      null;
    elsif old.action_outcome = 'PARTIAL' and new.action_outcome = 'FAILED' then
      select count(*) into confirmed
        from public.workflow_action_reconciliations x
       where x.run_id = new.id and x.result <> 'STILL_UNKNOWN';
      if confirmed = 0 then
        raise exception 'runs: PARTIAL may only be narrowed by a recorded reconciliation (run %)', new.id
          using errcode = 'restrict_violation';
      end if;
    else
      raise exception 'runs: illegal action outcome transition % → % (run %)',
        old.action_outcome, new.action_outcome, new.id using errcode = 'restrict_violation';
    end if;
  end if;

  if new.action_outcome = 'CANCELLED'
     and public.action_phase_rank(coalesce(new.action_phase, old.action_phase)) >= 3 then
    raise exception
      'runs: CANCELLED is not a legal outcome after DISPATCH_STARTED — the side effect may have happened (run %)',
      new.id using errcode = 'restrict_violation';
  end if;

  return new;
end $$;

drop trigger if exists runs_action_outcome_guard_trg on public.runs;
create trigger runs_action_outcome_guard_trg
  before update on public.runs
  for each row execute function public.runs_action_outcome_guard();

create or replace function omnira_cron.reap_stuck_runs()
returns int language plpgsql security definer set search_path to '' as $$
declare n int; m int;
begin
  update public.runs set
    status                  = 'unknown',
    action_outcome          = 'UNKNOWN',
    reconciliation_required = true,
    reconciliation_reason   = 'lease expired after dispatch; the side effect may or may not have been applied',
    outcome_recorded_at     = now(),
    finished_at             = now(),
    claimed_at              = null,
    lease_until             = null,
    claim_id                = null
  where status = 'running'
    and lease_until is not null and lease_until < now()
    and workflow_instance_id is not null
    and public.action_phase_rank(action_phase) >= 3;
  get diagnostics m = row_count;

  update public.runs set
    status      = case when attempts >= max_attempts then 'failed' else 'pending' end,
    error       = case when attempts >= max_attempts then coalesce(last_error,'Lease expired (stuck run)') else error end,
    finished_at = case when attempts >= max_attempts then now() else finished_at end,
    claimed_at  = null, lease_until = null, claim_id = null
  where status = 'running'
    and lease_until is not null and lease_until < now()
    and (workflow_instance_id is null or public.action_phase_rank(action_phase) < 3);
  get diagnostics n = row_count;

  return n + m;
end $$;

-- ─────────────────────────────────────────────────────────────────────────────
--  G2 — ATOMIC BUDGET SCOPES + REPLAY SAFETY.
--  (Header abbreviated in this application; canonical text lives in the repo at
--   apps/web/supabase/migrations/20260831_budget_scopes.sql @ 681f721.)
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.project_budgets
  add column if not exists daily_sek  numeric(12,4),
  add column if not exists weekly_sek numeric(12,4);

alter table public.project_budgets
  drop constraint if exists project_budgets_scopes_nonneg;
alter table public.project_budgets
  add constraint project_budgets_scopes_nonneg check (
    (daily_sek  is null or daily_sek  >= 0) and
    (weekly_sek is null or weekly_sek >= 0) and
    monthly_sek >= 0
  );

comment on column public.project_budgets.daily_sek is
  'G2: optional per-project daily ceiling (Europe/Stockholm day). NULL = not configured; the mandatory platform daily ceiling still applies.';
comment on column public.project_budgets.weekly_sek is
  'G2: optional per-project weekly ceiling (ISO week, Europe/Stockholm). NULL = not configured; the mandatory platform weekly ceiling still applies.';

alter table public.platform_config
  add column if not exists global_daily_sek   numeric(12,4),
  add column if not exists global_weekly_sek  numeric(12,4),
  add column if not exists global_monthly_sek numeric(12,4);

update public.platform_config
   set global_daily_sek   = coalesce(global_daily_sek,   150.0000),
       global_weekly_sek  = coalesce(global_weekly_sek,  600.0000),
       global_monthly_sek = coalesce(global_monthly_sek, 1500.0000)
 where id = 1;

alter table public.platform_config
  drop constraint if exists platform_config_global_budget_nonneg;
alter table public.platform_config
  add constraint platform_config_global_budget_nonneg check (
    (global_daily_sek   is null or global_daily_sek   >= 0) and
    (global_weekly_sek  is null or global_weekly_sek  >= 0) and
    (global_monthly_sek is null or global_monthly_sek >= 0)
  );

comment on column public.platform_config.global_daily_sek is
  'G2: mandatory platform-wide daily spend ceiling (Europe/Stockholm). budget_reserve refuses when absent.';

insert into public.project_budgets (project_id, monthly_sek, daily_sek, weekly_sek)
select p.id, 50.0000, 20.0000, 35.0000
from public.projects p
where p.slug = 'omnira-selftest'
  and not exists (select 1 from public.project_budgets b where b.project_id = p.id)
on conflict (project_id) do nothing;

update public.project_budgets b
   set daily_sek  = coalesce(b.daily_sek,  100.0000),
       weekly_sek = coalesce(b.weekly_sek, 400.0000)
  from public.projects p
 where p.id = b.project_id and p.slug = 'ai-media-automation';

alter table public.cost_events
  drop constraint if exists cost_events_cost_nonneg;
alter table public.cost_events
  add constraint cost_events_cost_nonneg check (cost_sek >= 0 and cost_usd >= 0);

create or replace function public.budget_scope_state(
  p_project_id    uuid,
  p_stale_minutes int default 30
) returns table (
  scope       text,
  limit_sek   numeric,
  spent_sek   numeric,
  held_sek    numeric,
  remaining_sek numeric
) language sql security definer set search_path to '' stable as $$
  with tz as (select 'Europe/Stockholm'::text as z),
  win as (
    select
      (l_day)                              at time zone z as d0,
      (l_day   + interval '1 day')         at time zone z as d1,
      (l_week)                             at time zone z as w0,
      (l_week  + interval '1 week')        at time zone z as w1,
      (l_month)                            at time zone z as m0,
      (l_month + interval '1 month')       at time zone z as m1,
      now() - make_interval(mins => p_stale_minutes)      as stale
    from (
      select z,
             date_trunc('day',   now() at time zone z) as l_day,
             date_trunc('week',  now() at time zone z) as l_week,
             date_trunc('month', now() at time zone z) as l_month
      from tz
    ) t
  ),
  lim as (
    select b.daily_sek, b.weekly_sek, b.monthly_sek,
           c.global_daily_sek, c.global_weekly_sek, c.global_monthly_sek
      from (select 1 as k) one
      left join public.project_budgets b on b.project_id = p_project_id
      left join public.platform_config c on c.id = 1
  ),
  scopes(scope, lim, since, until, all_projects) as (
    select 'project_daily',   lim.daily_sek,          win.d0, win.d1, false from lim, win
    union all select 'project_weekly',  lim.weekly_sek,  win.w0, win.w1, false from lim, win
    union all select 'project_monthly', lim.monthly_sek, win.m0, win.m1, false from lim, win
    union all select 'global_daily',    lim.global_daily_sek,   win.d0, win.d1, true from lim, win
    union all select 'global_weekly',   lim.global_weekly_sek,  win.w0, win.w1, true from lim, win
    union all select 'global_monthly',  lim.global_monthly_sek, win.m0, win.m1, true from lim, win
  )
  select s.scope, s.lim, x.spent, x.held, least(s.lim, s.lim - x.spent - x.held)
  from scopes s, win
  cross join lateral (
    select
      coalesce((select sum(greatest(c.cost_sek, 0)) from public.cost_events c
                 where c.created_at >= s.since and c.created_at < s.until
                   and (s.all_projects or c.project_id = p_project_id)), 0) as spent,
      coalesce((select sum(r.estimated_sek) from public.spend_reservations r
                 where r.status = 'open'
                   and r.created_at >= s.since and r.created_at < s.until
                   and r.created_at > win.stale
                   and (s.all_projects or r.project_id = p_project_id)), 0) as held
  ) x
  where s.lim is not null
  order by (s.lim - x.spent - x.held) asc;
$$;

revoke all on function public.budget_scope_state(uuid, int) from public, anon, authenticated;
grant execute on function public.budget_scope_state(uuid, int) to service_role;

-- G2 adds an EIGHTH output column, `binding_scope`, so the row type changes from
-- 7 to 8. PostgreSQL refuses that through `create or replace` (42P13). NO
-- CASCADE: RESTRICT means an unexpected persistent dependent aborts the whole
-- migration instead of being silently dropped. Verified against production:
-- zero catalog dependents, zero views/matviews/rules/triggers/cron jobs.
drop function if exists public.budget_reserve(uuid, numeric, text, text, text, int);

create or replace function public.budget_reserve(
  p_project_id      uuid,
  p_estimated_sek   numeric,
  p_idempotency_key text default null,
  p_provider        text default null,
  p_operation       text default null,
  p_stale_minutes   int  default 30
) returns table (
  allowed        boolean,
  reservation_id uuid,
  reason         text,
  budget_sek     numeric,
  committed_sek  numeric,
  reserved_sek   numeric,
  headroom_sek   numeric,
  binding_scope  text
) language plpgsql security definer set search_path to '' as $$
declare
  v_existing public.spend_reservations;
  v_id       uuid;
  v_has_proj boolean;
  v_has_glob boolean;
  v_scope    text;
  v_lim      numeric;
  v_spent    numeric;
  v_held     numeric;
  v_rem      numeric;
begin
  if p_estimated_sek is null
     or p_estimated_sek = 'NaN'::numeric
     or p_estimated_sek = 'Infinity'::numeric
     or p_estimated_sek = '-Infinity'::numeric
     or p_estimated_sek < 0 then
    return query select false, null::uuid, 'invalid_estimate',
                        null::numeric, null::numeric, null::numeric, null::numeric, null::text;
    return;
  end if;

  perform pg_advisory_xact_lock(hashtext('budget_reserve:' || p_project_id::text));
  perform pg_advisory_xact_lock(hashtext('budget_reserve:__platform__'));

  if p_idempotency_key is not null then
    select * into v_existing
      from public.spend_reservations where idempotency_key = p_idempotency_key;
    if found then
      if v_existing.project_id      is distinct from p_project_id
         or v_existing.provider     is distinct from p_provider
         or v_existing.operation    is distinct from p_operation
         or p_estimated_sek > v_existing.estimated_sek then
        return query select false, v_existing.id, 'replay_identity_mismatch'::text,
                            null::numeric, null::numeric, null::numeric, null::numeric, null::text;
        return;
      end if;

      if v_existing.status = 'open'
         and v_existing.created_at > now() - make_interval(mins => p_stale_minutes) then
        return query select false, v_existing.id, 'replay_in_flight'::text,
                            null::numeric, null::numeric, null::numeric, null::numeric, null::text;
      elsif v_existing.status = 'open' then
        update public.spend_reservations
           set status = 'released', resolved_at = now()
         where id = v_existing.id;
        return query select false, v_existing.id, 'replay_stale'::text,
                            null::numeric, null::numeric, null::numeric, null::numeric, null::text;
      elsif v_existing.status = 'settled' then
        return query select false, v_existing.id, 'replay_settled'::text,
                            null::numeric, null::numeric, null::numeric, null::numeric, null::text;
      else
        return query select false, v_existing.id, 'replay_released'::text,
                            null::numeric, null::numeric, null::numeric, null::numeric, null::text;
      end if;
      return;
    end if;
  end if;

  select exists (select 1 from public.project_budgets b
                  where b.project_id = p_project_id and b.monthly_sek is not null),
         exists (select 1 from public.platform_config c
                  where c.id = 1 and c.global_daily_sek is not null
                    and c.global_weekly_sek is not null and c.global_monthly_sek is not null)
    into v_has_proj, v_has_glob;

  if not v_has_proj then
    return query select false, null::uuid, 'no_budget_configured',
                        null::numeric, null::numeric, null::numeric, null::numeric, null::text;
    return;
  end if;
  if not v_has_glob then
    return query select false, null::uuid, 'no_global_budget_configured',
                        null::numeric, null::numeric, null::numeric, null::numeric, null::text;
    return;
  end if;

  select s.scope, s.limit_sek, s.spent_sek, s.held_sek, s.remaining_sek
    into v_scope, v_lim, v_spent, v_held, v_rem
    from public.budget_scope_state(p_project_id, p_stale_minutes) s
   order by s.remaining_sek asc
   limit 1;

  insert into public.spend_reservations (project_id, estimated_sek, provider, operation,
                                         idempotency_key, status)
  values (p_project_id, p_estimated_sek, p_provider, p_operation, p_idempotency_key,
          case when p_estimated_sek <= v_rem then 'open' else 'released' end)
  returning id into v_id;

  if p_estimated_sek <= v_rem then
    return query select true, v_id, 'ok'::text, v_lim, v_spent, v_held, v_rem, v_scope;
  else
    return query select false, v_id, 'budget_exceeded'::text, v_lim, v_spent, v_held, v_rem, v_scope;
  end if;
end $$;

revoke all on function public.budget_reserve(uuid, numeric, text, text, text, int) from public, anon, authenticated;
grant execute on function public.budget_reserve(uuid, numeric, text, text, text, int) to service_role;

drop function if exists public.budget_headroom(int);

create or replace function public.budget_headroom(p_stale_minutes int default 30)
returns table (
  project_id uuid, slug text, scope text,
  limit_sek numeric, spent_sek numeric, held_sek numeric, remaining_sek numeric
) language sql security definer set search_path to '' stable as $$
  select p.id, p.slug, s.scope, s.limit_sek, s.spent_sek, s.held_sek, s.remaining_sek
  from public.projects p
  cross join lateral public.budget_scope_state(p.id, p_stale_minutes) s
  order by p.slug, s.remaining_sek asc;
$$;

revoke all on function public.budget_headroom(int) from public, anon, authenticated;
grant execute on function public.budget_headroom(int) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- Governance G3B — make workflow transitions stop-atomic (closes F-107)
-- ═══════════════════════════════════════════════════════════════════════════
--
-- F-107 / G3-F-002, exactly:
--
--   T1  the application reads the stop state and sees "clear"
--   T2  an operator pauses, and that pause COMMITS
--   T3  the now-stale caller invokes workflow_append_transition(...)
--
-- Today T3 succeeds. The authoritative SQL that writes workflow_transitions and
-- advances workflow_instances.current_state consults NEITHER stop authority --
-- verified against production: the deployed body contains no reference to
-- automation_paused or execution_paused. Every stop check lived in TypeScript,
-- one round trip earlier, which is precisely the window.
--
-- G3B moves the check INTO the transaction that does the writing, under row
-- locks that conflict with the G3A setters. After this, a committed pause and a
-- committed transition are linearly ordered, and the ordering "pause commits,
-- then a transition commits on pre-pause state" becomes impossible.
--
-- WHAT THIS IS NOT. This does not make the platform stop-safe. It closes the
-- race at ONE mutation boundary: the workflow transition append. A paused
-- workflow can still be claimed by scheduler paths, still create runs, still
-- run provider work, and legacy media steps are untouched. Those are G3C/G3D.
-- Do not read this migration as "the global stop now stops all execution".
--
-- SIGNATURE UNCHANGED, so this is CREATE OR REPLACE with no DROP and no
-- CASCADE: same arguments, same return type, same owner, same SECURITY DEFINER,
-- same empty search_path, same service_role-only EXECUTE. Nothing but the
-- barrier is added -- the instance lock, the CAS, the state validation, the gate
-- derivation and the authorization chain are carried over verbatim from
-- 20260829_workflow_gate_authorization.sql.
--
-- NO BYPASS EXISTS. No p_context, no p_force, no GUC, no session variable, no
-- privileged actor and no authorization id can skip the barrier. A human
-- authorization does not override a stop, and a backward transition that needs
-- no gate does not either: pause freezes.

create or replace function public.workflow_append_transition(
  p_instance_id      uuid,
  p_from_state       text,
  p_to_state         text,
  p_reason           text,
  p_actor            text,
  p_evidence_ref     uuid default null,
  p_authorization_id uuid default null
) returns public.workflow_transitions
language plpgsql
security definer
set search_path to ''
as $$
declare
  i          public.workflow_instances;
  t          public.workflow_transitions;
  d_spec     jsonb;
  from_json  jsonb;
  terminal   boolean;
  gated      boolean;
  is_advance boolean;
  granted_n  int;
  closed_n   int;
  chain_n    int;
  gpaused    boolean;
  ppaused    boolean;
begin
  select * into i from public.workflow_instances where id = p_instance_id for update;
  if not found then
    raise exception 'workflow_append_transition: unknown instance %', p_instance_id
      using errcode = 'foreign_key_violation';
  end if;

  if i.status <> 'active' then
    raise exception 'workflow_append_transition: instance % is % and accepts no further transitions',
      p_instance_id, i.status
      using errcode = 'restrict_violation';
  end if;

  if p_from_state is null then
    raise exception 'workflow_append_transition: from_state is required (the opening transition belongs to workflow_instantiate)'
      using errcode = 'check_violation';
  end if;
  if i.current_state is distinct from p_from_state then
    raise exception 'workflow_append_transition: stale transition — instance % is in "%" not "%"',
      p_instance_id, i.current_state, p_from_state
      using errcode = 'serialization_failure';
  end if;

  -- ── G3B · STOP BARRIER (closes F-107) ──────────────────────────────────────
  --
  -- THE RACE THIS CLOSES. The application could read "not paused", an operator
  -- could then pause and COMMIT, and this function — which never consulted
  -- either stop authority — would still append the transition afterwards. The
  -- stale read was in TypeScript; the authoritative write was here; nothing
  -- connected them.
  --
  -- A workflow state transition is INTRINSICALLY execution-bearing, so both G3A
  -- enforcing scopes apply and there is deliberately no context parameter: a
  -- caller that could declare its own context could declare its way past the
  -- stop.
  --
  -- WHY FOR SHARE, AND WHY HERE. This function does not mutate the stop rows; it
  -- needs a lock that CONFLICTS with the G3A setters' FOR UPDATE and is held
  -- until this transaction ends. That yields exactly two orderings and no third:
  --
  --   • this transaction takes SHARE first → a concurrent pause BLOCKS until we
  --     commit → the transition linearized before the stop, which is correct;
  --   • the pause setter takes UPDATE first → we BLOCK, then read the COMMITTED
  --     paused value and refuse → no transition commits after the stop.
  --
  -- The forbidden third outcome — pause commits, then a transition commits on
  -- pre-pause state — is what F-107 was.
  --
  -- Placed AFTER the instance CAS so the existing fencing is untouched, and
  -- BEFORE any definition, gate or authorization work so a stopped scope costs
  -- nothing and can never append. Lock order is instance → platform → project;
  -- no canonical function locks a stop row before a workflow instance, so this
  -- introduces no cycle.
  select pc.automation_paused into gpaused
    from public.platform_config pc where pc.id = 1 for share;
  if not found then
    -- Fail closed. Treating a missing config row as "not paused" is how a kill
    -- switch becomes a no-op.
    raise exception 'workflow_append_transition: platform stop authority unavailable (platform_config row 1 missing)'
      using errcode = 'P0002';
  end if;

  select p.execution_paused into ppaused
    from public.projects p where p.id = i.project_id for share;
  if not found then
    raise exception 'workflow_append_transition: project stop authority unavailable for project %', i.project_id
      using errcode = 'P0002';
  end if;

  -- GLOBAL is reported first: it is the broader authority, and telling an
  -- operator "this project is stopped" while the whole platform is stopped sends
  -- them to fix the wrong thing. `restrict_violation` — never
  -- `insufficient_privilege` — so a stop refusal is distinguishable from an
  -- authorization refusal by SQLSTATE alone.
  if gpaused then
    raise exception 'workflow_append_transition: GLOBAL execution is stopped — no transition may be appended'
      using errcode = 'restrict_violation';
  end if;
  if ppaused then
    raise exception 'workflow_append_transition: PROJECT execution is stopped for % — no transition may be appended', i.project_id
      using errcode = 'restrict_violation';
  end if;

  select spec into d_spec from public.workflow_defs where id = i.def_id;
  if not exists (
    select 1 from jsonb_array_elements(d_spec -> 'states') s where s ->> 'id' = p_to_state
  ) then
    raise exception 'workflow_append_transition: state "%" is not declared by % v%',
      p_to_state, i.def_key, i.def_version
      using errcode = 'check_violation';
  end if;

  -- ── Gate check ─────────────────────────────────────────────────────────────
  -- Reading a declared flag out of the pinned spec, not re-deciding the graph.
  select s into from_json
  from jsonb_array_elements(d_spec -> 'states') s
  where s ->> 'id' = p_from_state;

  gated      := coalesce((from_json -> 'human_gate' ->> 'required')::boolean, false);
  -- Only crossing a gate FORWARD needs authority. Failing backwards is redoing
  -- your own work and needs none — same rule as the TypeScript machine.
  is_advance := (from_json ->> 'next_state') is not distinct from p_to_state;

  if gated and is_advance then
    if p_authorization_id is null then
      raise exception 'workflow_append_transition: leaving "%" crosses a required human gate — an authorization is required',
        p_from_state
        using errcode = 'insufficient_privilege';
    end if;

    select
      count(*),
      count(*) filter (
        where a.event_type = 'granted'
          and a.expires_at is not null
          and a.expires_at > now()
          and a.target_type = 'workflow_gate'
          and a.target_id = p_instance_id::text || ':' || p_from_state
          and a.project_id = i.project_id
      ),
      count(*) filter (
        where a.event_type in ('denied', 'revoked', 'superseded', 'expired')
      )
    into chain_n, granted_n, closed_n
    from public.atlas_authorizations a
    where a.authorization_id = p_authorization_id;

    if chain_n = 0 then
      raise exception 'workflow_append_transition: authorization % does not exist', p_authorization_id
        using errcode = 'insufficient_privilege';
    end if;
    if closed_n > 0 then
      raise exception 'workflow_append_transition: authorization % was denied, revoked, superseded or expired',
        p_authorization_id
        using errcode = 'insufficient_privilege';
    end if;
    if granted_n = 0 then
      raise exception 'workflow_append_transition: authorization % carries no live grant for instance % state "%"',
        p_authorization_id, p_instance_id, p_from_state
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  insert into public.workflow_transitions (
    instance_id, from_state, to_state, reason, actor, evidence_ref, authorization_id
  ) values (
    p_instance_id, p_from_state, p_to_state, p_reason, p_actor, p_evidence_ref, p_authorization_id
  ) returning * into t;

  select coalesce(
    (select (s -> 'next_state') = 'null'::jsonb or s -> 'next_state' is null
     from jsonb_array_elements(d_spec -> 'states') s where s ->> 'id' = p_to_state),
    false
  ) into terminal;

  update public.workflow_instances set
    current_state = p_to_state,
    status        = case when terminal then 'complete' else status end,
    closed_at     = case when terminal then now() else closed_at end
  where id = p_instance_id;

  return t;
end;
$$;

-- Privileges restated for the record. CREATE OR REPLACE preserves them, so these
-- are assertions of intent rather than changes: if the deployed ACL ever drifts,
-- re-running this migration restores it.
revoke all on function public.workflow_append_transition(uuid, text, text, text, text, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.workflow_append_transition(uuid, text, text, text, text, uuid, uuid)
  to service_role;

insert into storage.buckets (id, name, public)
values ('media-assets-private', 'media-assets-private', false)
on conflict (id) do nothing;

create table if not exists public.assets (
  id                uuid primary key default gen_random_uuid(),
  project_id        uuid not null references public.projects(id) on delete cascade,
  kind              text not null check (kind in ('image', 'video', 'audio')),
  mime_type         text not null,
  byte_size         bigint not null check (byte_size > 0),
  checksum_sha256   text not null check (checksum_sha256 ~ '^[0-9a-f]{64}$'),
  width             integer check (width  is null or width  > 0),
  height            integer check (height is null or height > 0),
  duration_ms       integer check (duration_ms is null or duration_ms >= 0),
  visibility        text not null default 'internal'
                      check (visibility in ('internal', 'public')),
  status            text not null default 'active'
                      check (status in ('active', 'archived', 'superseded')),
  storage_bucket    text not null,
  storage_path      text not null,
  created_at        timestamptz not null default now(),
  constraint assets_storage_object_unique unique (storage_bucket, storage_path)
);

create index if not exists assets_project_created_idx
  on public.assets (project_id, created_at desc);

create index if not exists assets_project_kind_idx
  on public.assets (project_id, kind);

create index if not exists assets_checksum_idx
  on public.assets (project_id, checksum_sha256);

comment on table public.assets is
  'Canonical Omnira media asset identity (Intelligence Fabric ch21). The id is the durable handle; storage_bucket/storage_path are current location, not identity (§21.9). Distinct from public.outputs, which is the Output (§21.4).';

comment on column public.assets.visibility is
  'internal (default, fail-closed) or public. Admission refuses to place a non-public asset in a public bucket; visibility is never inferred from where the bytes landed.';

comment on column public.assets.storage_path is
  'Current location only. Moving an object does not change the asset identity. Never parse a URL to obtain this.';

create table if not exists public.asset_provenance (
  asset_id             uuid primary key
                         references public.assets(id) on delete cascade,
  source               text not null
                         check (source in ('generated', 'uploaded', 'derived', 'imported')),
  provider             text,
  model                text,
  provider_request_id  text,
  adapter_version      text,
  seed                 text,
  brief_hash           text check (brief_hash   is null or brief_hash   ~ '^[0-9a-f]{64}$'),
  request_hash         text check (request_hash is null or request_hash ~ '^[0-9a-f]{64}$'),
  reference_asset_ids  uuid[] not null default '{}',
  cost_event_id        uuid,
  duration_ms          integer check (duration_ms is null or duration_ms >= 0),
  simulated            boolean not null default false,
  provider_metadata    jsonb not null default '{}'::jsonb,
  recorded_at          timestamptz not null default now()
);

create index if not exists asset_provenance_provider_idx
  on public.asset_provenance (provider, model);

comment on table public.asset_provenance is
  'What produced one asset. Written at admission (§21.5), append-only. Provider fields are a record, never an authority: naming a provider here permits nothing.';

comment on column public.asset_provenance.cost_event_id is
  'Link to cost_events. Intentionally not an FK: cost logging is fire-and-forget and must never be able to fail an admission. This is never an amount — cost_events is the only ledger.';

comment on column public.asset_provenance.reference_asset_ids is
  'Canonical reference assets by identity, never URL. Admission requires each to exist in the SAME project (Project Isolation).';

create or replace function public.asset_reject_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception
    '% is append-only: % is not permitted', tg_table_name, tg_op
    using errcode = 'restrict_violation';
end;
$$;

drop trigger if exists asset_provenance_no_update on public.asset_provenance;
create trigger asset_provenance_no_update
  before update on public.asset_provenance
  for each row execute function public.asset_reject_mutation();

create or replace function public.asset_provenance_reject_orphan_delete()
returns trigger
language plpgsql
as $$
begin
  if exists (select 1 from public.assets where id = old.asset_id) then
    raise exception
      'asset_provenance is append-only: DELETE is not permitted while asset % exists', old.asset_id
      using errcode = 'restrict_violation';
  end if;
  return old;
end;
$$;

drop trigger if exists asset_provenance_no_delete on public.asset_provenance;
create trigger asset_provenance_no_delete
  before delete on public.asset_provenance
  for each row execute function public.asset_provenance_reject_orphan_delete();

alter table public.assets            enable row level security;
alter table public.asset_provenance  enable row level security;

drop policy if exists "assets_owner" on public.assets;
create policy "assets_owner" on public.assets
  for all using (
    project_id in (select id from public.projects where owner_id = auth.uid())
  );

drop policy if exists "asset_provenance_owner" on public.asset_provenance;
create policy "asset_provenance_owner" on public.asset_provenance
  for all using (
    asset_id in (
      select a.id from public.assets a
      join public.projects p on p.id = a.project_id
      where p.owner_id = auth.uid()
    )
  );

alter table public.website_content
