comment on column public.website_content.hero_asset_id is
  'Canonical asset identity for the hero image (Phase 1, forward-only). NULL means the row predates the asset system and hero_image_url is a legacy delivery URL — not that anything is wrong.';

-- Project-scoped social credentials — owner decision 1A (2026-09-14): The Prompt's
-- existing Instagram, Facebook and YouTube accounts are bound to The Prompt from
-- the verified runtime evidence the owner approved.
--
-- NOTHING IS ASSUMED. Each binding is inserted only if its evidence still holds at
-- apply time, inside this transaction. Any drift raises, and the whole migration
-- rolls back having bound nothing:
--
--   instagram  @theprompt.news · 17841437027967629
--              The newest Instagram snapshot of the project was captured AFTER the
--              stored credential was last refreshed, carries no error, and carries
--              this user_id and username — Instagram's /me answer for the
--              credential stored now.
--   facebook   page 1138612202672850
--              It is the stored credential's account_id; the newest Facebook
--              snapshot read that page node without error; and Meta accepted a
--              Facebook post for the project after the credential was last stored.
--   youtube    channel UCUM9JDi75ziLssYcGLo8IPA
--              The newest YouTube snapshot of the project resolves the project's
--              own uploads to this channel.
--
-- NO CREDENTIAL IS TOUCHED. platform_tokens is read, never written. The YouTube
-- credential stays in Vercel (Y1) and is attached to The Prompt's binding only.
-- Labels are only what a provider attested: the Instagram username from the
-- snapshot. The Facebook page name and YouTube channel title were never stored, so
-- they stay empty until a live verification records them, and
-- verification = 'runtime_evidence' says exactly that.
--
-- FRESH DATABASES. Without the project, or without its stored credentials, there
-- is nothing to bind and the migration does nothing. A second run refuses rather
-- than binding twice.

do $$
declare
  v_project       uuid;
  v_ig_refreshed  timestamptz;
  v_fb_refreshed  timestamptz;
  v_fb_account    text;
  v_ig_raw        jsonb;
  v_ig_at         timestamptz;
  v_fb_raw        jsonb;
  v_fb_at         timestamptz;
  v_yt_raw        jsonb;
  v_yt_at         timestamptz;
  v_bound_by constant text := 'migration:social_account_bindings_the_prompt_evidence';
begin
  select id into v_project from public.projects where slug = 'ai-media-automation';
  if v_project is null then
    raise notice 'social account evidence: project ai-media-automation absent — nothing to bind';
    return;
  end if;

  select refreshed_at into v_ig_refreshed
    from public.platform_tokens where project_id = v_project and platform = 'instagram';
  select refreshed_at, account_id into v_fb_refreshed, v_fb_account
    from public.platform_tokens where project_id = v_project and platform = 'facebook';

  if v_ig_refreshed is null and v_fb_refreshed is null then
    raise notice 'social account evidence: The Prompt holds no stored credentials — nothing to bind';
    return;
  end if;
  if v_ig_refreshed is null or v_fb_refreshed is null then
    raise exception 'social account evidence: The Prompt must hold both its stored Instagram and Facebook credentials';
  end if;

  if exists (select 1 from public.social_account_bindings where project_id = v_project) then
    raise exception 'social account evidence: The Prompt already has bindings — refusing to bind twice';
  end if;

  -- ── Instagram ─────────────────────────────────────────────────────────────
  select s.raw, s.captured_at into v_ig_raw, v_ig_at
    from public.account_snapshots s
   where s.project_id = v_project and s.platform = 'instagram'
   order by s.captured_at desc
   limit 1;
  if not found
     or jsonb_typeof(v_ig_raw) is distinct from 'object'
     or v_ig_raw ? 'error'
     or (v_ig_raw ->> 'user_id') is distinct from '17841437027967629'
     or lower(v_ig_raw ->> 'username') is distinct from 'theprompt.news'
     or v_ig_at < v_ig_refreshed then
    raise exception 'social account evidence drift: instagram';
  end if;

  -- ── Facebook ──────────────────────────────────────────────────────────────
  if v_fb_account is distinct from '1138612202672850' then
    raise exception 'social account evidence drift: facebook stored account';
  end if;
  select s.raw, s.captured_at into v_fb_raw, v_fb_at
    from public.account_snapshots s
   where s.project_id = v_project and s.platform = 'facebook'
   order by s.captured_at desc
   limit 1;
  if not found
     or jsonb_typeof(v_fb_raw) is distinct from 'object'
     or v_fb_raw ? 'error'
     or (v_fb_raw ->> 'id') is distinct from '1138612202672850' then
    raise exception 'social account evidence drift: facebook snapshot';
  end if;
  if not exists (
    select 1 from public.media_scripts m
     where m.project_id = v_project
       and m.facebook_post_id is not null
       and m.published_at >= v_fb_refreshed
  ) then
    raise exception 'social account evidence drift: no facebook publication with the stored credential';
  end if;

  -- ── YouTube ───────────────────────────────────────────────────────────────
  select s.raw, s.captured_at into v_yt_raw, v_yt_at
    from public.account_snapshots s
   where s.project_id = v_project and s.platform = 'youtube'
   order by s.captured_at desc
   limit 1;
  if not found
     or jsonb_typeof(v_yt_raw) is distinct from 'object'
     or (v_yt_raw -> 'items' -> 0 ->> 'id') is distinct from 'UCUM9JDi75ziLssYcGLo8IPA' then
    raise exception 'social account evidence drift: youtube';
  end if;
  if not exists (
    select 1 from public.media_scripts m
     where m.project_id = v_project and m.youtube_video_id is not null
  ) then
    raise exception 'social account evidence drift: no youtube upload for the project';
  end if;

  insert into public.social_account_bindings
    (project_id, platform, external_account_id, account_label, credential_source, verification, verified_at, bound_by)
  values
    (v_project, 'instagram', '17841437027967629', v_ig_raw ->> 'username', 'project_store',             'runtime_evidence', v_ig_at, v_bound_by),
    (v_project, 'facebook',  '1138612202672850',  null,                    'project_store',             'runtime_evidence', v_fb_at, v_bound_by),
    (v_project, 'youtube',   'UCUM9JDi75ziLssYcGLo8IPA', null,             'platform_env_transitional', 'runtime_evidence', v_yt_at, v_bound_by);

  raise notice 'social account evidence: bound The Prompt instagram 17841437027967629, facebook 1138612202672850, youtube UCUM9JDi75ziLssYcGLo8IPA';
end;
$$;

-- SDF-1C1B: claim-scoped broker credential foundation (control plane only).
--
-- Activates the dormant broker_token_* seam that SDF-1B1 reserved on
-- atlas_code_work_runs. One opaque credential exists per claim; ONLY its
-- SHA-256 hash is ever persisted, and it lives exactly as long as the claim
-- lease. The raw token is generated and hashed by the trusted server-side
-- caller and never crosses into SQL.
--
-- This migration adds NO table, NO route, NO broker-facing capability and NO
-- execution path. The credential is possession evidence for a claim that the
-- existing SQL boundary has already authorised; it grants nothing by itself.
--
-- SDF-1B1 (20260918095827) is canonical history and is not edited. Cancel,
-- timeout and terminal transitions already clear broker_token_hash and
-- broker_token_expires_at (and the claim), so they are left untouched.
--
-- No begin/commit: the migration runner owns the transaction, so the whole
-- change applies or fails atomically.

-- 1. Replace the dormant-only shape with the credential shape.
--    No claim  -> no token material.
--    Claim     -> a lowercase SHA-256 hash and an expiry equal to the lease.
alter table public.atlas_code_work_runs
  drop constraint atlas_code_work_runs_token_dormant_check;

alter table public.atlas_code_work_runs
  add constraint atlas_code_work_runs_claim_credential_check check (
    (claim_id is null and broker_token_hash is null and broker_token_expires_at is null)
    or (
      claim_id is not null
      -- Explicit not-null tests: a CHECK that evaluates to NULL PASSES, so a missing
      -- hash must be rejected by a definite false, not by a NULL regex match.
      and broker_token_hash is not null
      and broker_token_hash ~ '^[a-f0-9]{64}$'
      and broker_token_expires_at is not null
      and broker_token_expires_at = lease_until
    )
  );

-- 2. The credential-less claim can no longer create a claim. It is removed
--    outright rather than stubbed, so no overload can bypass the credential.
drop function public.atlas_code_work_claim(uuid, text, text);

create function public.atlas_code_work_claim(
  p_work_id uuid,
  p_broker_id text,
  p_broker_host_id text,
  p_broker_token_hash text
)
returns public.atlas_code_work_runs
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_run public.atlas_code_work_runs;
  v_expiry timestamptz;
  v_runtime_cap timestamptz;
  v_lease timestamptz;
  v_claim uuid := gen_random_uuid();
  v_fence bigint;
begin
  if coalesce(p_broker_id,'')='' or coalesce(p_broker_host_id,'')='' then
    raise exception 'broker identity placeholders required' using errcode='invalid_parameter_value';
  end if;
  if p_broker_token_hash is null or p_broker_token_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'broker claim credential hash invalid' using errcode='invalid_parameter_value';
  end if;
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id for update;
  if not found then raise exception 'code-work run not found' using errcode='no_data_found'; end if;
  if v_run.state <> 'authorized' or v_run.cancel_requested or v_run.claim_id is not null then
    raise exception 'code-work run is not claimable' using errcode='object_not_in_prerequisite_state';
  end if;
  v_expiry := public.atlas_code_work_authorization_expiry(v_run);
  if v_expiry is null then return public.atlas_code_work_cancel_locked(v_run,v_run.requested_by,'authorization_ineffective'); end if;
  v_runtime_cap := v_run.created_at + ((v_run.admission#>>'{limits,maxTotalRuntimeSeconds}')::integer * interval '1 second');
  if v_runtime_cap <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'runtime_cap_elapsed'); end if;
  v_lease := least(clock_timestamp()+interval '90 seconds',v_expiry,v_runtime_cap);
  v_fence := v_run.fence+1;
  perform public.atlas_code_work_append_control_locked(v_run,'transition',
    jsonb_build_object('from','authorized','to','claimed'),'lifecycle');
  perform set_config('omnira.code_work_control','on',true);
  update public.atlas_code_work_runs set state='claimed',state_version=state_version+1,
    claim_id=v_claim,fence=v_fence,broker_id=p_broker_id,broker_host_id=p_broker_host_id,
    lease_until=v_lease,last_heartbeat_at=clock_timestamp(),authorization_expires_at=v_expiry,
    broker_token_hash=p_broker_token_hash,broker_token_expires_at=v_lease
   where work_id=p_work_id returning * into v_run;
  -- The receipt records THAT a credential exists, never the credential or its hash.
  perform public.atlas_code_work_append_control_locked(v_run,'claim_issued',
    jsonb_build_object('claimId',v_claim::text,'fence',v_fence,'leaseUntil',v_lease,
      'credentialIssued',true),'claim');
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id;
  return v_run;
end
$fn$;

revoke all on function public.atlas_code_work_claim(uuid, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.atlas_code_work_claim(uuid, text, text, text) to service_role;

-- 3. Heartbeat: the token lives exactly as long as the lease. The token itself
--    is NOT rotated; only its expiry follows the renewed lease. Every other
--    check (claim, fence, cancellation, lease, authorization, runtime cap) is
--    unchanged. Same signature, so create-or-replace keeps owner and ACL.
create or replace function public.atlas_code_work_heartbeat(
  p_work_id uuid,
  p_claim_id uuid,
  p_fence bigint
)
returns public.atlas_code_work_runs
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_run public.atlas_code_work_runs;
  v_expiry timestamptz;
  v_cap timestamptz;
  v_lease timestamptz;
begin
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id for update;
  if not found then raise exception 'code-work run not found' using errcode='no_data_found'; end if;
  if v_run.claim_id is distinct from p_claim_id or v_run.fence <> p_fence then
    raise exception 'stale code-work fence' using errcode='serialization_failure';
  end if;
  if v_run.cancel_requested or v_run.state in ('ready_for_human_review','tests_failed','scope_violation','stale_base','worker_failed','cancelled','timeout','policy_denied') then
    raise exception 'code-work run is not heartbeat eligible' using errcode='object_not_in_prerequisite_state';
  end if;
  if v_run.lease_until <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'lease_expired'); end if;
  v_expiry := public.atlas_code_work_authorization_expiry(v_run);
  if v_expiry is null then return public.atlas_code_work_cancel_locked(v_run,v_run.requested_by,'authorization_ineffective'); end if;
  v_cap := v_run.created_at + ((v_run.admission#>>'{limits,maxTotalRuntimeSeconds}')::integer * interval '1 second');
  if v_cap <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'runtime_cap_elapsed'); end if;
  v_lease := least(clock_timestamp()+interval '90 seconds',v_expiry,v_cap);
  perform set_config('omnira.code_work_control','on',true);
  update public.atlas_code_work_runs set lease_until=v_lease,last_heartbeat_at=clock_timestamp(),
    authorization_expires_at=v_expiry,broker_token_expires_at=v_lease
   where work_id=p_work_id returning * into v_run;
  perform public.atlas_code_work_append_control_locked(v_run,'lease_renewed',
    jsonb_build_object('claimId',p_claim_id::text,'fence',p_fence,'leaseUntil',v_lease,
      'heartbeatTargetSeconds',30),'heartbeat');
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id;
  return v_run;
end
$fn$;

-- SDF-1C2: authenticated broker control channel (database side).
--
-- Adds ONLY what the discover -> claim -> claim-recovery -> heartbeat channel
-- needs. No table, no work-context storage, no sandbox/worker/model/execution
-- object. SDF-1B1 and SDF-1C1B are canonical history and are not edited.
--
--  1. A control receipt event, `claim_credential_reissued`, so that a credential
--     reissue is auditable WITHOUT secret material. No existing event says this
--     truthfully (`claim_issued` would falsely imply a new claim).
--  2. atlas_code_work_heartbeat now REQUIRES the claim proof. The credential-less
--     3-argument signature is dropped; the proof (claim id, fence, broker id, broker
--     host id and the credential HASH) is verified inside the same row lock that
--     renews the lease, so there is no read-then-heartbeat window. The raw token
--     never crosses into SQL; only its domain-separated SHA-256 does.
--  3. atlas_code_work_discover_claimable: a purpose-specific, bounded, closed-shape read
--     for broker discovery (work id, repository id, pinned base sha and nothing else).
--  4. atlas_code_work_recover_claim_credential: same-broker recovery of a claim
--     whose response carrying the raw token was lost. It replaces the credential
--     HASH only. It never creates a claim, never changes claim id, fence, work,
--     repository, authority or admission, never renews the lease, and is closed
--     for good once a lease renewal (first heartbeat) has been receipted.
--
-- No begin/commit: the migration runner owns the transaction.

-- 1. Receipt vocabulary.
alter table public.atlas_code_work_receipts
  drop constraint atlas_code_work_receipts_event_type_check;

alter table public.atlas_code_work_receipts
  add constraint atlas_code_work_receipts_event_type_check check (event_type in (
    'proposal_created', 'authorization_requested', 'authorization_effective',
    'authorization_refused', 'claim_issued', 'claim_credential_reissued',
    'lease_renewed', 'cancellation', 'transition', 'evidence'
  ));

-- 2. Credential-bearing heartbeat. The old signature is removed, not stubbed.
drop function public.atlas_code_work_heartbeat(uuid, uuid, bigint);

create function public.atlas_code_work_heartbeat(
  p_work_id uuid,
  p_claim_id uuid,
  p_fence bigint,
  p_broker_id text,
  p_broker_host_id text,
  p_broker_token_hash text
)
returns public.atlas_code_work_runs
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_run public.atlas_code_work_runs;
  v_expiry timestamptz;
  v_cap timestamptz;
  v_lease timestamptz;
begin
  if p_broker_token_hash is null or p_broker_token_hash !~ '^[a-f0-9]{64}$'
     or coalesce(p_broker_id,'')='' or coalesce(p_broker_host_id,'')='' then
    raise exception 'broker claim proof invalid' using errcode='invalid_parameter_value';
  end if;
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id for update;
  if not found then raise exception 'code-work run not found' using errcode='no_data_found'; end if;
  -- One uniform refusal for every proof mismatch (claim, fence, broker, host, credential),
  -- evaluated under the row lock, so nothing distinguishes which part was wrong.
  if v_run.claim_id is distinct from p_claim_id or v_run.fence <> p_fence
     or v_run.broker_id is distinct from p_broker_id
     or v_run.broker_host_id is distinct from p_broker_host_id
     or v_run.broker_token_hash is distinct from p_broker_token_hash then
    raise exception 'stale code-work fence' using errcode='serialization_failure';
  end if;
  if v_run.cancel_requested or v_run.state in ('ready_for_human_review','tests_failed','scope_violation','stale_base','worker_failed','cancelled','timeout','policy_denied') then
    raise exception 'code-work run is not heartbeat eligible' using errcode='object_not_in_prerequisite_state';
  end if;
  if v_run.lease_until <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'lease_expired'); end if;
  v_expiry := public.atlas_code_work_authorization_expiry(v_run);
  if v_expiry is null then return public.atlas_code_work_cancel_locked(v_run,v_run.requested_by,'authorization_ineffective'); end if;
  v_cap := v_run.created_at + ((v_run.admission#>>'{limits,maxTotalRuntimeSeconds}')::integer * interval '1 second');
  if v_cap <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'runtime_cap_elapsed'); end if;
  v_lease := least(clock_timestamp()+interval '90 seconds',v_expiry,v_cap);
  perform set_config('omnira.code_work_control','on',true);
  update public.atlas_code_work_runs set lease_until=v_lease,last_heartbeat_at=clock_timestamp(),
    authorization_expires_at=v_expiry,broker_token_expires_at=v_lease
   where work_id=p_work_id returning * into v_run;
  perform public.atlas_code_work_append_control_locked(v_run,'lease_renewed',
    jsonb_build_object('claimId',p_claim_id::text,'fence',p_fence,'leaseUntil',v_lease,
      'heartbeatTargetSeconds',30),'heartbeat');
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id;
  return v_run;
end
$fn$;

revoke all on function public.atlas_code_work_heartbeat(uuid, uuid, bigint, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.atlas_code_work_heartbeat(uuid, uuid, bigint, text, text, text) to service_role;

-- 3. Same-broker credential recovery for the claim handshake only.
create function public.atlas_code_work_recover_claim_credential(
  p_work_id uuid,
  p_broker_id text,
  p_broker_host_id text,
  p_broker_token_hash text
)
returns public.atlas_code_work_runs
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_run public.atlas_code_work_runs;
  v_expiry timestamptz;
  v_cap timestamptz;
begin
  if p_broker_token_hash is null or p_broker_token_hash !~ '^[a-f0-9]{64}$'
     or coalesce(p_broker_id,'')='' or coalesce(p_broker_host_id,'')='' then
    raise exception 'broker claim credential hash invalid' using errcode='invalid_parameter_value';
  end if;
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id for update;
  -- Unknown work, someone else's claim, an unclaimed run, a run past the handshake
  -- state and a cancelled run all refuse identically.
  if not found
     or v_run.state <> 'claimed' or v_run.claim_id is null or v_run.cancel_requested
     or v_run.broker_id is distinct from p_broker_id
     or v_run.broker_host_id is distinct from p_broker_host_id
     or v_run.broker_token_hash is null
     or v_run.broker_token_hash = p_broker_token_hash then
    raise exception 'claim credential is not recoverable' using errcode='object_not_in_prerequisite_state';
  end if;
  -- The handshake ends with the first receipted lease renewal: from then on possession
  -- of the claim credential is required and identity alone can never re-mint it.
  if exists (
    select 1 from public.atlas_code_work_receipts r
     where r.work_id = p_work_id and r.event_type = 'lease_renewed'
  ) then
    raise exception 'claim credential is not recoverable' using errcode='object_not_in_prerequisite_state';
  end if;
  if v_run.lease_until <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'lease_expired'); end if;
  v_expiry := public.atlas_code_work_authorization_expiry(v_run);
  if v_expiry is null then return public.atlas_code_work_cancel_locked(v_run,v_run.requested_by,'authorization_ineffective'); end if;
  v_cap := v_run.created_at + ((v_run.admission#>>'{limits,maxTotalRuntimeSeconds}')::integer * interval '1 second');
  if v_cap <= clock_timestamp() then return public.atlas_code_work_timeout_locked(v_run,'runtime_cap_elapsed'); end if;
  -- Replace the credential HASH only. Lease, token expiry (= lease), fence, claim id and
  -- every authority field are untouched: recovery grants no additional runtime.
  perform set_config('omnira.code_work_control','on',true);
  update public.atlas_code_work_runs set broker_token_hash=p_broker_token_hash
   where work_id=p_work_id returning * into v_run;
  -- Non-secret audit: THAT a credential was reissued, never the credential or its hash.
  perform public.atlas_code_work_append_control_locked(v_run,'claim_credential_reissued',
    jsonb_build_object('claimId',v_run.claim_id::text,'fence',v_run.fence,'leaseUntil',v_run.lease_until,
      'credentialReissued',true),'claim_recovery');
  select * into v_run from public.atlas_code_work_runs where work_id=p_work_id;
  return v_run;
end
$fn$;

revoke all on function public.atlas_code_work_recover_claim_credential(uuid, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.atlas_code_work_recover_claim_credential(uuid, text, text, text) to service_role;

-- 4. Broker discovery: advisory, closed-shape, bounded. Appearing here is NOT proof the run
--    is still claimable; the claim function re-checks everything under the row lock.
create function public.atlas_code_work_discover_claimable(
  p_repository_ids text[],
  p_limit integer default 20
)
returns table (work_id uuid, repository_id text, pinned_base_sha text)
language sql
stable
security definer
set search_path = ''
as $fn$
  select r.work_id, r.repository_id, r.pinned_base_sha
    from public.atlas_code_work_runs r
   where r.state = 'authorized'
     and r.claim_id is null
     and not r.cancel_requested
     and r.repository_id = any(coalesce(p_repository_ids, array[]::text[]))
     and (r.authorization_expires_at is null or r.authorization_expires_at > clock_timestamp())
   order by r.authorized_at asc nulls last, r.work_id asc
   limit least(greatest(coalesce(p_limit, 20), 1), 20)
$fn$;

revoke all on function public.atlas_code_work_discover_claimable(text[], integer)
  from public, anon, authenticated, service_role;
grant execute on function public.atlas_code_work_discover_claimable(text[], integer) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- Phase 3B1B2 · M3 — commit clock + self-probing Survival fence (INERT)
-- ═══════════════════════════════════════════════════════════════════════════
--
-- WHY
--   M2 answers "did any DATABASE Survival input change?". Time changes Survival
--   too, with no row changing: the Europe/Stockholm day/week/month budget windows
--   roll, open undispatched reservations go stale after 30 minutes, and cost rows
--   age out of the 30-day burn window. M3 answers "is the observation still valid
--   at the moment a future licensed bind (M4) is allowed to commit?".
--
-- WHAT (and nothing more — the licensed bind RPC and its provenance are M4;
-- licensed binds still return licensed_bind_not_serializable)
--
--   A. survival_observation_anchor() — the DB clock (clock_timestamp()) and the
--      M2 epoch vector in ONE statement. A fence-grade observation is anchored to
--      this DB instant, never to an application clock.
--   B. survival_clock_invalid_at(anchor) — the EARLIEST instant at which an
--      observation anchored at `anchor` may stop being valid because time passed.
--      Derived from the canonical read semantics (no TTL):
--        - next Europe/Stockholm midnight / ISO-week start / month start — the
--          budget_scope_state window boundaries (DST-correct local arithmetic);
--        - min(created_at + 30 min) over open UNDISPATCHED reservations — the
--          budget_scope_state stale rule (p_stale_minutes = 30, as the snapshot
--          passes it);
--        - min(created_at + 720 h) over cost rows inside the 30-day burn window
--          anchored at `anchor` (720 EXACT hours: the burn cutoff is
--          at − 30·86 400 000 ms, never "30 calendar days").
--      Every input is read over ALL projects, so the deadline never depends on a
--      caller-chosen scope and is never later than the scoped truth.
--      Equality: the observation is invalid AT the instant (reject >=).
--   C. survival_commit_fence(observed_vector, anchor) — INTERNAL (no role may
--      execute it; only a future SECURITY DEFINER bind function can). Self-probes,
--      registers a COMMIT-TIME recheck, locks the 8 shards FOR SHARE in ascending
--      order AS ITS LAST LOCKS, compares the vector exactly, checks
--      clock_timestamp() < invalid_at.
--   D. A deferred constraint trigger re-runs the shard + clock check at COMMIT.
--   E. A guard on the shard table: a fenced transaction may not change Survival
--      authority at all — whether the write came before or after the fence, and
--      whatever order its deferred M2 bump fires in at commit.
--
-- THE CLOCK. Only clock_timestamp() is used as the validity clock: now(),
-- CURRENT_TIMESTAMP, transaction_timestamp() and statement_timestamp() are the
-- transaction/statement START, not the wall clock at the fence or at commit.
--
-- LOCK ORDER (the shard rows are the fence's LAST locks)
--   1. reads (MVCC; never wait on a Survival writer) to compute invalid_at;
--   2. own-row writes to survival_commit_fence_intents (no Survival writer ever
--      touches it); stale-intent cleanup uses SKIP LOCKED, so it never waits;
--   3. survival_input_epoch_shards 0 → 7 FOR SHARE, one at a time, in order.
--   Nothing after step 3 takes a lock or reads a table a writer can hold.
--   M2 writers take their shard as their FINAL lock (deferred, at commit), so a
--   writer and a fence can only meet on the shard rows: the writer waits for the
--   fence's commit; the fence never waits on anything the writer holds.
--
-- COMMIT-TIME, HONESTLY
--   PostgreSQL has no ON COMMIT hook in SQL; a deferred constraint trigger is the
--   latest point a check can run, and it runs at COMMIT under the default
--   constraint mode. So:
--   - the recheck runs at commit in the default mode, which is the only mode on
--     the canonical path;
--   - forcing it IMMEDIATE before the fence is DETECTED and refused (SV007);
--   - any Survival authority write in the fenced transaction aborts it (SV006),
--     in either order, so a post-fence statement cannot change authority;
--   - a caller able to run arbitrary SQL could still SET CONSTRAINTS … IMMEDIATE
--     AFTER the fence and then wait before COMMIT. That is why the fence has NO
--     grant: M4's bind must be the single-statement SECURITY DEFINER transaction
--     that calls it last (an M4 precondition, recorded, not assumed here).
--   The residual after the commit-time recheck is the commit record itself.
--
-- TWO-PHASE COMMIT. Deferred triggers fire at PREPARE TRANSACTION, not at COMMIT
-- PREPARED, so a prepared fenced transaction could commit arbitrarily later.
-- With max_prepared_transactions = 0, PREPARE TRANSACTION is impossible. The
-- fence and the recheck refuse unless the LIVE setting is 0 (SV001).
--
-- REFUSAL CODES (raised; the whole transaction aborts — fail closed)
--   SV001 prepared transactions enabled      SV006 fenced transaction changed authority
--   SV002 observed vector malformed          SV007 commit-time recheck forced IMMEDIATE
--   SV003 shard set malformed                SV008 anchor missing or in the future
--   SV004 epoch vector changed               SV009 fence not at transaction top level
--   SV005 clock validity expired             (23505 a second fence in one transaction)
--
-- NOT APPLIED BY THIS BRANCH.

-- ── 1. Fence intents: one row per fenced transaction ─────────────────────────
-- Change-identity plumbing, not authority and not provenance: it carries only
-- what the commit-time recheck needs. Rows of committed transactions are swept
-- by later fences (SKIP LOCKED); a rolled-back fence leaves nothing.
create table public.survival_commit_fence_intents (
  xact            xid8        primary key,
  anchor          timestamptz not null,
  observed_vector bigint[]    not null,
  invalid_at      timestamptz not null,
  fenced_at       timestamptz not null
);

comment on table public.survival_commit_fence_intents is
  'Phase 3B1B2 M3: one row per fenced transaction (full xid8), read by the commit-time recheck and by '
  'the shard guard that refuses Survival authority writes inside a fenced transaction. Not authority, '
  'not provenance. No role holds any privilege on it.';

-- ── 2. The DB anchor: clock + vector in one statement ────────────────────────
create or replace function public.survival_observation_anchor()
returns table (anchor timestamptz, epoch_vector bigint[])
language sql volatile security definer set search_path = '' as $$
  select pg_catalog.clock_timestamp(), public.survival_input_epoch_vector();
$$;

-- ── 3. The clock-validity deadline ───────────────────────────────────────────
create or replace function public.survival_clock_invalid_at(p_anchor timestamptz)
returns timestamptz language plpgsql stable security definer set search_path = '' as $$
declare
  z       constant text := 'Europe/Stockholm';
  v_day   timestamptz;
  v_week  timestamptz;
  v_month timestamptz;
  v_stale timestamptz;
  v_burn  timestamptz;
begin
  if p_anchor is null or p_anchor = 'infinity'::timestamptz or p_anchor = '-infinity'::timestamptz then
    raise exception 'survival_fence: anchor is missing' using errcode = 'SV008';
  end if;
  -- budget_scope_state's own window arithmetic, at the anchor.
  v_day   := (pg_catalog.date_trunc('day',   p_anchor at time zone z) + interval '1 day')   at time zone z;
  v_week  := (pg_catalog.date_trunc('week',  p_anchor at time zone z) + interval '1 week')  at time zone z;
  v_month := (pg_catalog.date_trunc('month', p_anchor at time zone z) + interval '1 month') at time zone z;
  -- budget_scope_state's stale rule: counted while created_at > now() − 30 min.
  select pg_catalog.min(r.created_at + interval '30 minutes') into v_stale
    from public.spend_reservations r
   where r.status = 'open' and r.dispatched_at is null
     and r.created_at + interval '30 minutes' > p_anchor;
  -- the 30-day burn window: counted while created_at >= at − 720 h (ms-truncated at).
  select pg_catalog.min(c.created_at + interval '720 hours') into v_burn
    from public.cost_events c
   where c.created_at >= pg_catalog.date_trunc('milliseconds', p_anchor) - interval '720 hours';
  return least(v_day, v_week, v_month, v_stale, v_burn);  -- LEAST is SQL syntax (ignores NULLs), not a catalog function
end $$;

-- ── 4. The commit-time recheck ───────────────────────────────────────────────
-- Fired by the deferred constraint trigger on the intent row: at COMMIT under the
-- default constraint mode. Re-locks the 8 shards FOR SHARE in ascending order
-- (already held by the fence, so it never waits) and repeats every check against
-- the values the fence stored. Leaves a transaction-local marker so the fence can
-- tell whether it was fired IMMEDIATELY (SV007).
create or replace function public.survival_commit_fence_recheck()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_ids    smallint[];
  v_epochs bigint[];
  v_own    boolean;
  i        smallint;
begin
  perform pg_catalog.set_config('omnira.survival_fence_rechecked', new.xact::text, true);
  if pg_catalog.current_setting('max_prepared_transactions')::int <> 0 then
    raise exception 'survival_fence: prepared transactions are enabled' using errcode = 'SV001';
  end if;
  for i in 0..7 loop
    perform 1 from public.survival_input_epoch_shards s where s.shard_id = i for share;
  end loop;
  select pg_catalog.array_agg(s.shard_id order by s.shard_id),
         pg_catalog.array_agg(s.epoch    order by s.shard_id),
         pg_catalog.bool_or(s.last_bump_xid is not distinct from new.xact)
    into v_ids, v_epochs, v_own
    from public.survival_input_epoch_shards s;
  if v_ids is distinct from array[0, 1, 2, 3, 4, 5, 6, 7]::smallint[] then
    raise exception 'survival_fence: shard set is malformed at commit' using errcode = 'SV003';
  end if;
  if v_own then
    raise exception 'survival_fence: the fenced transaction changed Survival authority' using errcode = 'SV006';
  end if;
  if v_epochs is distinct from new.observed_vector then
    raise exception 'survival_fence: Survival inputs changed before commit' using errcode = 'SV004';
  end if;
  if pg_catalog.clock_timestamp() >= new.invalid_at then
    raise exception 'survival_fence: observation clock validity expired at commit (%)', new.invalid_at
      using errcode = 'SV005';
  end if;
  return null;
end $$;

create constraint trigger survival_commit_fence_recheck
  after insert on public.survival_commit_fence_intents
  deferrable initially deferred for each row
  execute function public.survival_commit_fence_recheck();

-- ── 5. No Survival authority write inside a fenced transaction ───────────────
-- Every committed authority write reaches the shard table through the M2 bump
-- (an UPDATE). A fenced transaction's bump — from a write before OR after the
-- fence, fired at commit in any order — is refused here. M2's own objects are
-- unchanged; this is an additional BEFORE UPDATE trigger.
create or replace function public.survival_fenced_transaction_guard()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from public.survival_commit_fence_intents i
              where i.xact = pg_catalog.pg_current_xact_id()) then
    raise exception 'survival_fence: a fenced transaction may not change Survival authority'
      using errcode = 'SV006';
  end if;
  return new;
end $$;

create trigger survival_fenced_transaction_guard
  before update on public.survival_input_epoch_shards
  for each row execute function public.survival_fenced_transaction_guard();

-- ── 6. The fence ─────────────────────────────────────────────────────────────
create or replace function public.survival_commit_fence(p_observed_vector bigint[], p_anchor timestamptz)
returns timestamptz language plpgsql volatile security definer set search_path = '' as $$
declare
  v_xact     xid8 := pg_catalog.pg_current_xact_id();
  v_invalid  timestamptz;
  v_row_xmin bigint;
  v_ids      smallint[];
  v_epochs   bigint[];
  v_own      boolean;
  i          smallint;
begin
  -- Self-probes that need no lock.
  if pg_catalog.current_setting('max_prepared_transactions')::int <> 0 then
    raise exception 'survival_fence: prepared transactions are enabled' using errcode = 'SV001';
  end if;
  if p_observed_vector is null
     or pg_catalog.array_ndims(p_observed_vector) is distinct from 1
     or pg_catalog.array_lower(p_observed_vector, 1) is distinct from 1
     or pg_catalog.array_length(p_observed_vector, 1) is distinct from 8
     or pg_catalog.array_position(p_observed_vector, null) is not null
     or exists (select 1 from pg_catalog.unnest(p_observed_vector) e where e < 0) then
    raise exception 'survival_fence: observed epoch vector is malformed' using errcode = 'SV002';
  end if;
  if p_anchor is null or p_anchor > pg_catalog.clock_timestamp()
     or p_anchor = '-infinity'::timestamptz then
    raise exception 'survival_fence: anchor is missing or in the future' using errcode = 'SV008';
  end if;

  -- 1. Reads: the deadline. MVCC; never waits on a Survival writer.
  v_invalid := public.survival_clock_invalid_at(p_anchor);

  -- 2. Own-row writes. Sweep committed intents of other transactions without
  --    waiting, then register this transaction (a second fence → 23505).
  delete from public.survival_commit_fence_intents d
   where d.xact in (select o.xact from public.survival_commit_fence_intents o
                     where o.xact <> v_xact for update skip locked);
  insert into public.survival_commit_fence_intents (xact, anchor, observed_vector, invalid_at, fenced_at)
  values (v_xact, p_anchor, p_observed_vector, v_invalid, pg_catalog.clock_timestamp());

  -- The intent row must belong to the TOP-LEVEL transaction: a fence inside a
  -- savepoint or an EXCEPTION block could be rolled back with its locks while the
  -- rest commits. (Probe, not identity: the row was written by THIS transaction a
  -- moment ago, so its xmin is either the top-level xid or a subtransaction's.)
  select (x.xmin::text)::bigint into v_row_xmin from public.survival_commit_fence_intents x where x.xact = v_xact;
  if v_row_xmin is distinct from ((v_xact::text)::numeric % 4294967296)::bigint then
    raise exception 'survival_fence: must run at transaction top level' using errcode = 'SV009';
  end if;
  -- The recheck must still be pending. If it already ran, the constraint was
  -- forced IMMEDIATE and the commit-time check would not happen at commit.
  if pg_catalog.current_setting('omnira.survival_fence_rechecked', true) is not distinct from v_xact::text then
    raise exception 'survival_fence: commit-time recheck was forced IMMEDIATE' using errcode = 'SV007';
  end if;

  -- 3. LAST LOCKS: the 8 shards FOR SHARE, 0 → 7.
  for i in 0..7 loop
    perform 1 from public.survival_input_epoch_shards s where s.shard_id = i for share;
  end loop;
  select pg_catalog.array_agg(s.shard_id order by s.shard_id),
         pg_catalog.array_agg(s.epoch    order by s.shard_id),
         pg_catalog.bool_or(s.last_bump_xid is not distinct from v_xact)
    into v_ids, v_epochs, v_own
    from public.survival_input_epoch_shards s;
  if v_ids is distinct from array[0, 1, 2, 3, 4, 5, 6, 7]::smallint[] then
    raise exception 'survival_fence: shard set is malformed' using errcode = 'SV003';
  end if;
  if v_own then
    raise exception 'survival_fence: this transaction already changed Survival authority' using errcode = 'SV006';
  end if;
  if v_epochs is distinct from p_observed_vector then
    raise exception 'survival_fence: Survival inputs changed since the observation' using errcode = 'SV004';
  end if;
  if pg_catalog.clock_timestamp() >= v_invalid then
    raise exception 'survival_fence: observation clock validity expired (%)', v_invalid using errcode = 'SV005';
  end if;
  return v_invalid;
end $$;

comment on function public.survival_commit_fence(bigint[], timestamptz) is
  'Phase 3B1B2 M3: INERT commit fence for a future licensed bind (M4). Internal: no role may execute it. '
  'Refuses (raises SV001–SV009) unless the observed epoch vector still holds, the DB-clock validity '
  'deadline has not passed, and the transaction can be checked again at commit.';

-- ── 7. Privileges ────────────────────────────────────────────────────────────
alter table public.survival_commit_fence_intents enable row level security;
revoke all on table public.survival_commit_fence_intents from public, anon, authenticated, service_role;

revoke all on function public.survival_commit_fence(bigint[], timestamptz) from public, anon, authenticated, service_role;
revoke all on function public.survival_commit_fence_recheck() from public, anon, authenticated, service_role;
revoke all on function public.survival_fenced_transaction_guard() from public, anon, authenticated, service_role;
revoke all on function public.survival_observation_anchor() from public, anon, authenticated;
grant execute on function public.survival_observation_anchor() to service_role;
revoke all on function public.survival_clock_invalid_at(timestamptz) from public, anon, authenticated;
grant execute on function public.survival_clock_invalid_at(timestamptz) to service_role;

-- ─────────────────────────────────────────────────────────────────────────────
-- Handlarbörsen guarded snapshot store (Atlas collector P1E, part 1: protection)
--
-- Problem: the collector wrote today's snapshot with an unconditional upsert on
-- (project_id, snapshot_date). A later, incomplete collection could overwrite a complete
-- report, and two overlapping runs could race each other past any check done in the app.
--
-- Fix: ONE narrow SECURITY DEFINER function is the only write path to the table. The
-- decision and the write happen in one transaction under a row lock, so concurrent runs
-- serialize on the row and cannot bypass the rule. service_role loses INSERT and UPDATE
-- on the table; it keeps SELECT (the report reader) and gains EXECUTE on this function.
--
-- Rule (per snapshot_date row; quality = number of available metrics, 11 = complete):
--   no row yet                               -> inserted
--   more available metrics than stored       -> upgraded   (even if the observation is older)
--   equal quality and strictly newer         -> refreshed
--   equal quality and same observed_at       -> unchanged  (no write)
--   fewer available metrics than stored      -> rejected   (reason lower_quality)
--   equal quality and older observation      -> rejected   (reason older_observation)
-- A complete row (11) can therefore only be replaced by a newer complete observation.
--
-- Hard limits enforced here, not in the app:
--   * only today's UTC date can be written (older days are immutable history), and the
--     observation itself must fall on that date and not lie in the future;
--   * the project is fixed in the function; there is no project parameter;
--   * completeness is DERIVED from the metrics, never trusted from the caller;
--   * a metric is a non-negative integer or JSON null. null is stored as NULL, never 0;
--     `unavailable` must name exactly the null metrics, each with a known reason.
--
-- Purely additive apart from tightening service_role on one table. Creates no cron job and
-- schedules nothing. The cron activation is a separate, manually approved step.
--
-- ROLLBACK (restores the P1B state; safe at any time, no data is touched):
--   REVOKE EXECUTE ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM service_role;
--   DROP FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb);
--   GRANT INSERT, UPDATE ON TABLE public.handlarborsen_marketplace_snapshots TO service_role;
-- (The P1B collector code that upserts directly needs those grants back.)
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.handlarborsen_store_marketplace_snapshot(
  p_snapshot_date date,
  p_observed_at   timestamptz,
  p_unavailable   jsonb,
  p_metrics       jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $fn$
DECLARE
  c_project constant uuid   := '8f673c09-1c8f-4d78-876e-4c14bf1c89b3';
  c_keys    constant text[] := ARRAY[
    'companies_registered_total', 'companies_verified_total', 'vehicles_published_active',
    'vehicles_reserved', 'vehicles_published_last_24h', 'bids_total', 'bids_last_24h',
    'interests_last_24h', 'offers_last_24h', 'deals_completed_total', 'deals_completed_last_24h'
  ];
  v_key          text;
  v_val          jsonb;
  v_null_keys    text[] := ARRAY[]::text[];
  v_unavail_keys text[];
  v_reason       jsonb;
  v_available    integer;
  v_completeness text;
  v_inserted     boolean;
  v_old          record;
  v_old_avail    integer;
  v_outcome      text;
  v_reject       text;
BEGIN
  -- ── Input validation (fixed codes; never echoes input) ──────────────────────────
  IF p_snapshot_date IS NULL OR p_observed_at IS NULL THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:missing_argument' USING ERRCODE = '22023';
  END IF;
  IF p_snapshot_date <> (now() AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:not_today' USING ERRCODE = '22023';
  END IF;
  IF (p_observed_at AT TIME ZONE 'UTC')::date <> p_snapshot_date
     OR p_observed_at > now() + interval '10 minutes' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:observed_at' USING ERRCODE = '22023';
  END IF;

  IF p_metrics IS NULL OR jsonb_typeof(p_metrics) <> 'object'
     OR p_unavailable IS NULL OR jsonb_typeof(p_unavailable) <> 'object' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:shape' USING ERRCODE = '22023';
  END IF;
  IF (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM jsonb_object_keys(p_metrics) AS k)
     <> (SELECT array_agg(k ORDER BY k) FROM unnest(c_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_keys' USING ERRCODE = '22023';
  END IF;

  FOREACH v_key IN ARRAY c_keys LOOP
    v_val := p_metrics -> v_key;
    IF jsonb_typeof(v_val) = 'null' THEN
      v_null_keys := v_null_keys || v_key;
    ELSIF jsonb_typeof(v_val) = 'number' THEN
      -- Non-negative integer only: no sign, fraction or exponent, and below 2^53.
      IF v_val::text !~ '^[0-9]{1,15}$' THEN
        RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_value' USING ERRCODE = '22023';
      END IF;
    ELSE
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_type' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- `unavailable` names exactly the null metrics, each with a known reason.
  SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) INTO v_unavail_keys
    FROM jsonb_object_keys(p_unavailable) AS k;
  IF v_unavail_keys <> (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM unnest(v_null_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_keys' USING ERRCODE = '22023';
  END IF;
  FOREACH v_key IN ARRAY v_unavail_keys LOOP
    v_reason := p_unavailable -> v_key;
    IF jsonb_typeof(v_reason) <> 'string' OR (v_reason #>> '{}') NOT IN ('query_failed', 'invalid_count') THEN
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_reason' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  v_available    := array_length(c_keys, 1) - coalesce(array_length(v_null_keys, 1), 0);
  v_completeness := CASE
    WHEN v_available = array_length(c_keys, 1) THEN 'complete'
    WHEN v_available = 0 THEN 'unavailable'
    ELSE 'partial'
  END;

  -- ── Insert-or-decide, serialized on the row ─────────────────────────────────────
  -- A concurrent insert for the same day blocks on the unique index and then sees DO
  -- NOTHING; every later step takes the row lock first, so two runs can never both decide
  -- against the same stale state.
  INSERT INTO public.handlarborsen_marketplace_snapshots (
    project_id, snapshot_date, observed_at, captured_at, schema_version, window_hours,
    completeness, unavailable,
    companies_registered_total, companies_verified_total, vehicles_published_active,
    vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
    interests_last_24h, offers_last_24h, deals_completed_total, deals_completed_last_24h
  ) VALUES (
    c_project, p_snapshot_date, p_observed_at, now(), 1, 24,
    v_completeness, p_unavailable,
    (p_metrics ->> 'companies_registered_total')::bigint, (p_metrics ->> 'companies_verified_total')::bigint,
    (p_metrics ->> 'vehicles_published_active')::bigint, (p_metrics ->> 'vehicles_reserved')::bigint,
    (p_metrics ->> 'vehicles_published_last_24h')::bigint, (p_metrics ->> 'bids_total')::bigint,
    (p_metrics ->> 'bids_last_24h')::bigint, (p_metrics ->> 'interests_last_24h')::bigint,
    (p_metrics ->> 'offers_last_24h')::bigint, (p_metrics ->> 'deals_completed_total')::bigint,
    (p_metrics ->> 'deals_completed_last_24h')::bigint
  )
  ON CONFLICT (project_id, snapshot_date) DO NOTHING
  RETURNING true INTO v_inserted;

  IF v_inserted THEN
    RETURN jsonb_build_object(
      'outcome', 'inserted', 'stored', true, 'snapshot_date', p_snapshot_date,
      'completeness', v_completeness, 'available_count', v_available
    );
  END IF;

  SELECT completeness, observed_at,
         num_nonnulls(companies_registered_total, companies_verified_total, vehicles_published_active,
                      vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
                      interests_last_24h, offers_last_24h, deals_completed_total,
                      deals_completed_last_24h) AS available
    INTO v_old
    FROM public.handlarborsen_marketplace_snapshots
   WHERE project_id = c_project AND snapshot_date = p_snapshot_date
     FOR UPDATE;

  IF NOT FOUND THEN
    -- Unreachable: the row existed a moment ago and no role may delete it.
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:row_vanished' USING ERRCODE = '55000';
  END IF;
  v_old_avail := v_old.available;

  IF v_available > v_old_avail THEN
    v_outcome := 'upgraded';
  ELSIF v_available = v_old_avail AND p_observed_at > v_old.observed_at THEN
    v_outcome := 'refreshed';
  ELSIF v_available = v_old_avail AND p_observed_at = v_old.observed_at THEN
    v_outcome := 'unchanged';
  ELSE
    v_outcome := 'rejected';
    v_reject  := CASE WHEN v_available < v_old_avail THEN 'lower_quality' ELSE 'older_observation' END;
  END IF;

  IF v_outcome IN ('upgraded', 'refreshed') THEN
    UPDATE public.handlarborsen_marketplace_snapshots SET
      observed_at = p_observed_at, captured_at = now(), completeness = v_completeness,
      unavailable = p_unavailable,
      companies_registered_total  = (p_metrics ->> 'companies_registered_total')::bigint,
      companies_verified_total    = (p_metrics ->> 'companies_verified_total')::bigint,
      vehicles_published_active   = (p_metrics ->> 'vehicles_published_active')::bigint,
      vehicles_reserved           = (p_metrics ->> 'vehicles_reserved')::bigint,
      vehicles_published_last_24h = (p_metrics ->> 'vehicles_published_last_24h')::bigint,
      bids_total                  = (p_metrics ->> 'bids_total')::bigint,
      bids_last_24h               = (p_metrics ->> 'bids_last_24h')::bigint,
      interests_last_24h          = (p_metrics ->> 'interests_last_24h')::bigint,
      offers_last_24h             = (p_metrics ->> 'offers_last_24h')::bigint,
      deals_completed_total       = (p_metrics ->> 'deals_completed_total')::bigint,
      deals_completed_last_24h    = (p_metrics ->> 'deals_completed_last_24h')::bigint
     WHERE project_id = c_project AND snapshot_date = p_snapshot_date;
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome,
    'stored', v_outcome IN ('upgraded', 'refreshed'),
    'reason', v_reject,
    'snapshot_date', p_snapshot_date,
    'completeness', v_completeness,
    'available_count', v_available,
    'existing_completeness', v_old.completeness,
    'existing_available_count', v_old_avail,
    'existing_observed_at', v_old.observed_at
  );
END;
$fn$;

COMMENT ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) IS
  'The only write path to handlarborsen_marketplace_snapshots. Atomic insert-or-decide under a row lock: '
  'a complete report is never replaced by a less complete one, an older observation never replaces a newer '
  'one of equal quality, only today (UTC) is writable. Returns {outcome, stored, ...}. Service role only.';

REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM anon;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) TO service_role;

-- The function is now the only writer. Without INSERT/UPDATE a direct upsert (the P1B code
-- path, or any future caller) cannot bypass the rule. SELECT stays for the report reader.
REVOKE INSERT, UPDATE ON TABLE public.handlarborsen_marketplace_snapshots FROM service_role;
